import { config } from 'dotenv';
import { drizzle } from 'drizzle-orm/node-postgres';
import { Pool } from 'pg';

config();
config({ path: '../../.env' });

const connectionString =
  process.env.DATABASE_URL ?? 'postgres://brain:brain@localhost:5432/secondbrain';

export const pool = new Pool({ connectionString });
export const db = drizzle({ client: pool });
import 'dotenv/config';
import { defineConfig } from 'drizzle-kit';

export default defineConfig({
  dialect: 'postgresql',
  schema: './src/db/schema.ts',
  out: './drizzle',
  dbCredentials: {
    url: process.env.DATABASE_URL ?? 'postgres://brain:brain@localhost:5432/secondbrain',
  },
  strict: true,
  verbose: true,
});
# Copy to .env and paste the scoped, spend-capped key we send you
# (reply to your invite email to get one). This is the only external
# dependency — everything else runs locally in Docker.
ANTHROPIC_API_KEY=<set>

